const DAY = 86_400_000;
const apartments = [
  {id:'alamos',name:'Casa Álamos',area:'Centro histórico',capacity:3,size:48,layout:'1 dormitorio · sofá cama',price:112,cleaning:34,image:'assets/casa-alamos-salon.png',checkIn:'15:00–21:00',checkOut:'Hasta las 11:00',description:'Un piso tranquilo en una calle peatonal del centro. El dormitorio da a un patio interior y el salón conserva los cierres de madera.',environment:'A unos minutos a pie del mercado y los museos. La calle es peatonal, pero hay un aparcamiento público a 450 m.',amenities:['Aire acondicionado','Cocina completa','Lavadora','Cuna bajo petición'],rules:['No se permiten fiestas','No se fuma','Silencio de 23:00 a 08:00'],published:true},
  {id:'malagueta',name:'Estudio Malagueta',area:'La Malagueta',capacity:2,size:32,layout:'Estudio · 1 cama doble',price:89,cleaning:26,image:'assets/estudio-malagueta.png',checkIn:'16:00–22:00',checkOut:'Hasta las 10:30',description:'Un estudio compacto para una o dos personas, con cocina pequeña y una mesa cómoda para desayunar o trabajar.',environment:'En una calle residencial cerca de la playa. El paseo marítimo queda a unos cinco minutos a pie.',amenities:['Aire acondicionado','Cocina compacta','Ascensor','Ducha amplia'],rules:['No se admiten mascotas','No se fuma','Máximo 2 huéspedes'],published:true},
  {id:'huelin',name:'Piso Huelin',area:'Huelin',capacity:5,size:68,layout:'2 dormitorios · 3 camas',price:128,cleaning:42,image:'assets/piso-huelin.png',checkIn:'15:30–20:30',checkOut:'Hasta las 11:00',description:'Una vivienda práctica para familias, con dos dormitorios separados, mesa para cinco y espacio para guardar carritos o maletas.',environment:'Barrio residencial con comercios cotidianos y mercado. La playa y la estación María Zambrano quedan a poca distancia.',amenities:['Cocina completa','Lavadora','Trona','Ventiladores de techo'],rules:['No se permiten fiestas','Mascotas previa consulta','Silencio de 22:30 a 08:00'],published:false}
];

const seedBookings = [
  {id:'SP-1042',apartmentId:'alamos',guest:'Laura Martín',email:'laura@example.test',phone:'600 000 101',checkIn:'2026-10-08',checkOut:'2026-10-11',guests:2,status:'confirmed',total:370},
  {id:'SP-1043',apartmentId:'malagueta',guest:'Pablo Ruiz',email:'pablo@example.test',phone:'600 000 102',checkIn:'2026-10-06',checkOut:'2026-10-09',guests:1,status:'confirmed',total:293},
  {id:'SP-1038',apartmentId:'huelin',guest:'Familia Vega',email:'vega@example.test',phone:'600 000 103',checkIn:'2026-10-01',checkOut:'2026-10-05',guests:4,status:'cancelled',total:554}
];

const state = {search:null,selected:null,cancelId:null,bookings:loadBookings(),session:true};
function loadBookings(){try{return JSON.parse(localStorage.getItem('staypilot-bookings'))||seedBookings}catch{return seedBookings}}
function saveBookings(){localStorage.setItem('staypilot-bookings',JSON.stringify(state.bookings))}
function parseDate(value){return new Date(`${value}T12:00:00`)}
function nights(a,b){return Math.round((parseDate(b)-parseDate(a))/DAY)}
function formatDate(value,opts={day:'numeric',month:'short',year:'numeric'}){return new Intl.DateTimeFormat('es-ES',opts).format(parseDate(value))}
function euro(value){return new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(value)}
function overlaps(aStart,aEnd,bStart,bEnd){return aStart < bEnd && bStart < aEnd}
function isAvailable(apartmentId,start,end){return !state.bookings.some(b=>b.apartmentId===apartmentId&&b.status==='confirmed'&&overlaps(start,end,b.checkIn,b.checkOut))}
function esc(value=''){return String(value).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}

function setDefaultDates(){const base=new Date();const start=new Date(base.getTime()+2*DAY);const end=new Date(base.getTime()+5*DAY);const iso=d=>d.toISOString().slice(0,10);document.querySelector('#check-in').value=iso(start);document.querySelector('#check-out').value=iso(end);document.querySelector('#check-in').min=iso(base);document.querySelector('#check-out').min=iso(new Date(base.getTime()+DAY))}
function cardTemplate(a){const unavailable=state.search&&!isAvailable(a.id,state.search.checkIn,state.search.checkOut);return `<article class="apartment-card"><img src="${a.image}" alt="Interior de ${a.name}" loading="lazy"><div class="card-body"><div class="card-top"><div><h3>${a.name}</h3><p class="location">${a.area}, Málaga</p></div><p class="price">${euro(a.price)} <small>/ noche</small></p></div><p class="facts">${a.capacity} huéspedes · ${a.size} m² · ${a.layout}</p><p class="card-description">${a.description}</p><div class="card-action">${unavailable?'<span class="status">No disponible</span>':`<button class="link-button" data-detail="${a.id}">Ver alojamiento</button>`}<span>Limpieza ${euro(a.cleaning)}</span></div></div></article>`}
function renderApartments(){const grid=document.querySelector('#apartments-grid');const eligible=apartments.filter(a=>a.published&&(!state.search||a.capacity>=state.search.guests));const available=state.search?eligible.filter(a=>isAvailable(a.id,state.search.checkIn,state.search.checkOut)):eligible;grid.innerHTML=eligible.map(cardTemplate).join('');const count=document.querySelector('#result-count');count.textContent=`${available.length} ${available.length===1?'alojamiento disponible':'alojamientos disponibles'}`;const notice=document.querySelector('#availability-message');if(state.search&&available.length===0){notice.hidden=false;notice.innerHTML='<strong>No hay disponibilidad para esas fechas.</strong> Prueba con otras fechas o reduce el número de huéspedes.'}else notice.hidden=true;document.querySelectorAll('[data-detail]').forEach(btn=>btn.addEventListener('click',()=>showDetail(btn.dataset.detail)))}
function validateSearch(){const start=document.querySelector('#check-in').value,end=document.querySelector('#check-out').value,guests=Number(document.querySelector('#guest-count').value),error=document.querySelector('#search-error');let message='';if(!start||!end)message='Indica las fechas de entrada y salida.';else if(parseDate(end)<=parseDate(start))message='La salida debe ser posterior a la entrada.';else if(nights(start,end)>30)message='Esta demo admite estancias de hasta 30 noches.';error.textContent=message;error.hidden=!message;return message?null:{checkIn:start,checkOut:end,guests}}
function showDetail(id){state.selected=apartments.find(a=>a.id===id);const a=state.selected;const detail=document.querySelector('#apartment-detail');detail.hidden=false;detail.innerHTML=`<div class="detail-layout"><div><img class="detail-photo" src="${a.image}" alt="Interior de ${a.name}"></div><div><p class="eyebrow">${a.area} · Datos ficticios</p><h2>${a.name}</h2><p>${a.description}</p><p>${a.environment}</p><div class="detail-meta"><span>${a.capacity} huéspedes</span><span>${a.size} m²</span><span>${a.layout}</span></div><h3>Servicios</h3><ul class="amenities">${a.amenities.map(x=>`<li>${x}</li>`).join('')}</ul><h3>Horarios y normas</h3><p><strong>Entrada:</strong> ${a.checkIn}<br><strong>Salida:</strong> ${a.checkOut}</p><ul>${a.rules.map(x=>`<li>${x}</li>`).join('')}</ul><button id="start-booking" class="button button-primary">Elegir fechas y reservar</button></div></div>`;document.querySelector('#start-booking').addEventListener('click',()=>showBooking(a));detail.scrollIntoView({behavior:'smooth'})}
function showBooking(a){if(!state.search){const valid=validateSearch();if(!valid){document.querySelector('.hero-copy').scrollIntoView({behavior:'smooth'});return}state.search=valid}const s=state.search,qty=nights(s.checkIn,s.checkOut),stay=qty*a.price,total=stay+a.cleaning;const section=document.querySelector('#booking-section');section.hidden=false;section.innerHTML=`<div class="booking-layout"><div><p class="eyebrow">Reserva directa</p><h2 id="booking-title">Tus datos</h2><p>Usaremos estos datos solo para preparar esta reserva de demostración.</p><form id="booking-form" class="booking-form" novalidate><label>Nombre y apellidos<input name="name" autocomplete="name" required></label><label>Correo electrónico<input name="email" type="email" autocomplete="email" required></label><label>Teléfono<input name="phone" type="tel" autocomplete="tel" required></label><label class="full"><input name="terms" type="checkbox" style="width:auto;min-height:0" required> He leído los horarios y las normas del alojamiento.</label><p id="booking-error" class="field-message full" role="alert" hidden></p><button class="button button-primary full" type="submit">Confirmar reserva · ${euro(total)}</button></form></div><aside class="summary"><p class="eyebrow">Resumen</p><h3>${a.name}</h3><div class="summary-row"><span>Fechas</span><strong>${formatDate(s.checkIn,{day:'numeric',month:'short'})} – ${formatDate(s.checkOut,{day:'numeric',month:'short'})}</strong></div><div class="summary-row"><span>Huéspedes</span><strong>${s.guests}</strong></div><div class="summary-row"><span>${qty} noches × ${euro(a.price)}</span><span>${euro(stay)}</span></div><div class="summary-row"><span>Limpieza</span><span>${euro(a.cleaning)}</span></div><p class="muted">La limpieza está incluida en el total.</p><div class="summary-row total"><span>Total</span><span>${euro(total)}</span></div></aside></div>`;document.querySelector('#booking-form').addEventListener('submit',e=>submitBooking(e,{qty,total}));section.scrollIntoView({behavior:'smooth'})}
function submitBooking(event,price){event.preventDefault();const form=new FormData(event.currentTarget),error=document.querySelector('#booking-error');const name=String(form.get('name')||'').trim(),email=String(form.get('email')||'').trim(),phone=String(form.get('phone')||'').trim();let message='';if(name.length<3)message='Escribe el nombre y los apellidos.';else if(!/^\S+@\S+\.\S+$/.test(email))message='Revisa el correo electrónico.';else if(phone.replace(/\D/g,'').length<9)message='Escribe un teléfono con al menos 9 cifras.';else if(!form.get('terms'))message='Debes aceptar los horarios y las normas antes de continuar.';if(message){error.textContent=message;error.hidden=false;return}
  const a=state.selected,s=state.search;
  if(!isAvailable(a.id,s.checkIn,s.checkOut)){error.textContent='Estas fechas acaban de dejar de estar disponibles. Elige otras fechas para continuar.';error.hidden=false;renderApartments();return}
  const booking={id:`SP-${String(Date.now()).slice(-5)}`,apartmentId:a.id,guest:name,email,phone,checkIn:s.checkIn,checkOut:s.checkOut,guests:s.guests,status:'confirmed',total:price.total};state.bookings.push(booking);saveBookings();document.querySelector('#booking-section').hidden=true;const confirm=document.querySelector('#confirmation-section');confirm.hidden=false;confirm.innerHTML=`<div class="confirmation-box"><p class="eyebrow">Reserva confirmada</p><h2>Ya está anotada, ${esc(name.split(' ')[0])}.</h2><p>Hemos bloqueado ${a.name} del ${formatDate(s.checkIn)} al ${formatDate(s.checkOut)} para evitar otra reserva en las mismas fechas.</p><p class="confirmation-ref">Referencia ${booking.id}</p><p><strong>${s.guests} huéspedes · ${price.qty} noches · ${euro(price.total)}</strong></p><button class="button button-secondary" data-view="admin">Ver en administración</button></div>`;confirm.querySelector('[data-view]').addEventListener('click',()=>switchView('admin'));renderApartments();renderAdmin();confirm.scrollIntoView({behavior:'smooth'})}

function switchView(view){document.querySelectorAll('.view').forEach(v=>v.classList.remove('is-active'));document.querySelector(`#${view}-view`).classList.add('is-active');document.querySelectorAll('.nav-link').forEach(n=>n.classList.toggle('is-active',n.dataset.view===view));if(view==='admin')renderAdmin();window.scrollTo({top:0,behavior:'smooth'})}
function renderAdmin(){const confirmed=state.bookings.filter(b=>b.status==='confirmed');const today='2026-10-06';const arrivals=confirmed.filter(b=>b.checkIn===today),departures=confirmed.filter(b=>b.checkOut===today);document.querySelector('#admin-date').textContent=new Intl.DateTimeFormat('es-ES',{weekday:'long',day:'numeric',month:'long'}).format(parseDate(today));document.querySelector('#admin-agenda').innerHTML=`<div class="admin-title-row"><div><p class="eyebrow">Martes, 6 de octubre</p><h2>Entradas y salidas</h2></div><button class="button button-secondary" data-admin-tab="calendar">Ver calendario</button></div><div class="stat-strip"><div class="stat"><strong>${arrivals.length}</strong><span>entradas hoy</span></div><div class="stat"><strong>${departures.length}</strong><span>salidas hoy</span></div><div class="stat"><strong>${confirmed.length}</strong><span>reservas activas</span></div></div><h3>Agenda de hoy</h3><div class="agenda-list">${agendaRows(arrivals,departures)}</div>`;renderCalendar();renderReservations();renderProperties();wireAdminTabs()}
function agendaRows(arrivals,departures){const items=[...departures.map(b=>({b,type:'Salida',time:'11:00'})),...arrivals.map(b=>({b,type:'Entrada',time:'16:00'}))];if(!items.length)return '<div class="empty-state"><h3>No hay movimientos hoy.</h3><p>Consulta el calendario para revisar los próximos días.</p></div>';return items.map(({b,type,time})=>{const a=apartments.find(x=>x.id===b.apartmentId);return `<article class="agenda-item"><span class="agenda-time">${time}</span><div><strong>${type} · ${a.name}</strong><br><span class="muted">${esc(b.guest)} · ${b.guests} huéspedes</span></div><span>${b.id}</span><span class="status">Confirmada</span></article>`}).join('')}
function renderCalendar(){const start=parseDate('2026-10-06');const days=Array.from({length:14},(_,i)=>new Date(start.getTime()+i*DAY));const head=`<div></div>${days.map(d=>`<div class="day">${new Intl.DateTimeFormat('es-ES',{weekday:'short',day:'numeric'}).format(d)}</div>`).join('')}`;const rows=apartments.map(a=>`<div class="property">${a.name}</div>${days.map(d=>{const iso=d.toISOString().slice(0,10);const booked=state.bookings.some(b=>b.apartmentId===a.id&&b.status==='confirmed'&&iso>=b.checkIn&&iso<b.checkOut);return `<div class="calendar-cell ${booked?'booked':''}" title="${booked?'Reservado':'Disponible'}"><span class="hidden">${booked?'Reservado':'Disponible'} el ${iso}</span></div>`}).join('')}`).join('');document.querySelector('#admin-calendar').innerHTML=`<div class="calendar-head"><div><p class="eyebrow">Disponibilidad</p><h2>Próximos 14 días</h2></div><p><span class="status">Reservado</span></p></div><div class="calendar-scroll"><div class="calendar-grid">${head}${rows}</div></div><p class="muted">Las celdas verdes corresponden a noches reservadas. La fecha de salida queda libre para una nueva entrada.</p>`}
function renderReservations(filter='all'){const rows=state.bookings.filter(b=>filter==='all'||b.status===filter).sort((a,b)=>b.checkIn.localeCompare(a.checkIn));document.querySelector('#admin-reservations').innerHTML=`<div class="admin-title-row"><div><p class="eyebrow">Historial</p><h2>Reservas</h2></div></div><div class="filter-row"><label>Estado <select id="status-filter"><option value="all">Todas</option><option value="confirmed">Confirmadas</option><option value="cancelled">Canceladas</option></select></label></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Referencia</th><th>Huésped</th><th>Alojamiento</th><th>Estancia</th><th>Total</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${rows.map(b=>{const a=apartments.find(x=>x.id===b.apartmentId);return `<tr><td>${b.id}</td><td>${esc(b.guest)}</td><td>${a.name}</td><td>${formatDate(b.checkIn,{day:'numeric',month:'short'})} – ${formatDate(b.checkOut,{day:'numeric',month:'short'})}</td><td>${euro(b.total)}</td><td>${b.status==='confirmed'?'Confirmada':'Cancelada'}</td><td>${b.status==='confirmed'?`<button class="link-button" data-cancel="${b.id}">Cancelar</button>`:'—'}</td></tr>`}).join('')}</tbody></table></div>`;const filterEl=document.querySelector('#status-filter');filterEl.value=filter;filterEl.addEventListener('change',()=>renderReservations(filterEl.value));document.querySelectorAll('[data-cancel]').forEach(btn=>btn.addEventListener('click',()=>{state.cancelId=btn.dataset.cancel;document.querySelector('#cancel-dialog').showModal()}))}
function renderProperties(){document.querySelector('#admin-properties').innerHTML=`<div class="admin-title-row"><div><p class="eyebrow">Contenido público</p><h2>Alojamientos</h2></div></div><p class="muted">Un alojamiento despublicado deja de aparecer en la búsqueda, pero conserva sus reservas.</p>${apartments.map(a=>`<article class="property-admin-row"><img src="${a.image}" alt=""><div><strong>${a.name}</strong><br><span class="muted">${a.published?'Visible en la web':'Despublicado'}</span></div><div class="property-actions"><button class="button button-secondary" data-toggle-property="${a.id}">${a.published?'Despublicar':'Publicar'}</button><label class="button button-secondary" for="photo-${a.id}">Cambiar foto</label><input class="hidden" id="photo-${a.id}" data-photo-input="${a.id}" type="file" accept="image/jpeg,image/png,image/webp"></div><p id="upload-${a.id}" class="upload-feedback" role="status"></p></article>`).join('')}`;document.querySelectorAll('[data-toggle-property]').forEach(btn=>btn.addEventListener('click',()=>{const a=apartments.find(x=>x.id===btn.dataset.toggleProperty);a.published=!a.published;renderProperties();renderApartments()}));document.querySelectorAll('[data-photo-input]').forEach(input=>input.addEventListener('change',()=>handlePhoto(input)))}
function handlePhoto(input){const file=input.files[0],feedback=document.querySelector(`#upload-${input.dataset.photoInput}`);if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){feedback.textContent='No se ha subido la foto. Usa un archivo JPG, PNG o WebP.';feedback.className='upload-feedback error';return}if(file.size>3*1024*1024){feedback.textContent='No se ha subido la foto. El archivo supera el límite de 3 MB.';feedback.className='upload-feedback error';return}const a=apartments.find(x=>x.id===input.dataset.photoInput);a.image=URL.createObjectURL(file);renderProperties();renderApartments();const next=document.querySelector(`#upload-${a.id}`);next.textContent='Foto actualizada para esta sesión de demostración.';next.className='upload-feedback'}
function wireAdminTabs(){document.querySelectorAll('[data-admin-tab]').forEach(btn=>btn.addEventListener('click',()=>{const tab=btn.dataset.adminTab;document.querySelectorAll('.admin-panel').forEach(p=>p.classList.remove('is-active'));document.querySelector(`#admin-${tab}`).classList.add('is-active');document.querySelectorAll('.side-link').forEach(l=>l.classList.toggle('is-active',l.dataset.adminTab===tab))}))}

document.querySelector('#search-form').addEventListener('submit',e=>{e.preventDefault();const value=validateSearch();if(!value)return;state.search=value;document.querySelector('#apartment-detail').hidden=true;document.querySelector('#booking-section').hidden=true;document.querySelector('#confirmation-section').hidden=true;renderApartments();document.querySelector('#apartments-title').scrollIntoView({behavior:'smooth'})});
document.querySelectorAll('[data-view]').forEach(btn=>btn.addEventListener('click',()=>switchView(btn.dataset.view)));
document.querySelector('#simulate-expiry').addEventListener('click',()=>{state.session=false;document.querySelector('#session-notice').hidden=false;document.querySelectorAll('.admin-panel button,.admin-panel select,.admin-panel input').forEach(el=>el.disabled=true)});
document.querySelector('#restore-session').addEventListener('click',()=>{state.session=true;document.querySelector('#session-notice').hidden=true;renderAdmin()});
document.querySelector('#confirm-cancel').addEventListener('click',()=>{const booking=state.bookings.find(b=>b.id===state.cancelId);if(booking){booking.status='cancelled';saveBookings();renderAdmin();renderApartments()}state.cancelId=null});
setDefaultDates();renderApartments();renderAdmin();
